css:
.d-sd{display:flex;align-items:center;gap:16px}
.d-sd-grid{display:grid;grid-template-columns:repeat(3,12px);gap:16px}
.d-sd-dot{--k:0;width:12px;height:12px;border-radius:999px;background:#2b4b8f;opacity:.22;animation:d-svg-stagger-dots-scan 900ms linear infinite;animation-delay:calc(120ms * var(--k))}
.d-sd-dot:nth-child(2){--k:1}
.d-sd-dot:nth-child(3){--k:2}
.d-sd-dot:nth-child(4){--k:3}
.d-sd-dot:nth-child(5){--k:4}
.d-sd-dot:nth-child(6){--k:5}
@keyframes d-svg-stagger-dots-scan{0%{opacity:.22}20%{opacity:1}55%{opacity:1}75%{opacity:.22}100%{opacity:.22}}
.d-sd.is-paused .d-sd-dot{animation-play-state:paused}
.d-sd-btn{font-family:var(--font-mono);font-size:var(--fs-11);letter-spacing:var(--tracking-mono-label);padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--muted);cursor:pointer}
.d-sd-btn:hover{border-color:var(--ink);color:var(--ink)}
.d-sd-btn:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@media (prefers-reduced-motion: reduce){.d-sd-dot{animation:none;opacity:1}}

init:
root => {
    const box = root.querySelector('.d-sd'), btn = box.querySelector('.d-sd-btn');
    btn.onclick = () => {
      const paused = box.classList.toggle('is-paused');
      btn.textContent = paused ? '继续' : '暂停';
      btn.setAttribute('aria-pressed', String(paused));
    };
  }
